1	import React, { useState, useEffect, useRef } from 'react';
2	import { useParams, useNavigate } from 'react-router-dom';
3	import { motion, AnimatePresence } from 'framer-motion';
4	import { getCardapioPorSlug } from '../../services/restauranteService';
5	import { useAuth } from '../../contexts/AuthContext';
6	import { ThemeToggle } from '../../contexts/ThemeContext';
7	import Icon from '../../components/AppIcon';
8	import { imgUrl } from '../../lib/imgUrl';
9	
10	const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
11	
12	/* ── Skeleton ────────────────────────────────────────────────────── */
13	const SkeletonProduto = () => (
14	  <div className="flex gap-4 p-4 bg-white rounded-2xl border border-[#E4E4E7] animate-pulse">
15	    <div className="flex-1 space-y-2">
16	      <div className="h-4 bg-[#E4E4E7] rounded-lg w-3/4" />
17	      <div className="h-3 bg-[#F4F4F5] rounded-lg w-full" />
18	      <div className="h-3 bg-[#F4F4F5] rounded-lg w-2/3" />
19	      <div className="h-7 bg-[#E4E4E7] rounded-xl w-24 mt-3" />
20	    </div>
21	    <div className="w-28 h-24 bg-[#F4F4F5] rounded-xl flex-shrink-0" />
22	  </div>
23	);
24	
25	/* ── Card produto ────────────────────────────────────────────────── */
26	const ProdutoCard = ({ produto, onAdicionar, qtd, restauranteFechado, somenteVitrine }) => {
27	  const temPromo = produto.tags?.includes('promo') && produto.preco_promo != null;
28	  const indisponivel = produto.disponivel === false || restauranteFechado;
29	  const precoFinal = temPromo ? produto.preco_promo : produto.price;
30	
31	  return (
32	    <motion.div
33	      layout
34	      whileHover={indisponivel ? {} : { y: -1 }}
35	      className={`flex gap-4 p-4 bg-white rounded-2xl border transition-all h-full ${
36	        indisponivel ? 'border-[#E4E4E7] opacity-60' : 'border-[#E4E4E7] hover:shadow-md hover:border-[#FF441F]/20'
37	      }`}
38	    >
39	      <div className="flex-1 flex flex-col justify-between min-w-0">
40	        <div>
41	          <div className="flex items-start gap-2 flex-wrap">
42	            <p className="font-semibold text-[#18181B] text-sm leading-snug flex-1">{produto.name}</p>
43	            {produto.destaque && (
44	              <span className="text-[10px] px-1.5 py-0.5 bg-yellow-400/20 text-yellow-700 rounded font-bold flex-shrink-0">⭐ Destaque</span>
45	            )}
46	            {produto.tags?.includes('mais_vendido') && (
47	              <span className="text-[10px] px-1.5 py-0.5 bg-amber-100 text-amber-700 rounded font-bold flex-shrink-0">🔥 Top</span>
48	            )}
49	          </div>
50	          {produto.description && (
51	            <p className="text-xs text-[#71717A] mt-1 line-clamp-2">{produto.description}</p>
52	          )}
53	        </div>
54	
55	        <div className="flex items-center justify-between mt-3 gap-2 flex-wrap">
56	          <div>
57	            {temPromo && <p className="text-xs line-through text-[#71717A]">{fmt(produto.price)}</p>}
58	            <div className="flex items-center gap-1.5">
59	              <p className={`text-base font-bold ${temPromo ? 'text-green-600' : 'text-[#FF441F]'}`}>{fmt(precoFinal)}</p>
60	              {temPromo && <span className="text-[10px] bg-green-100 text-green-700 px-1.5 py-0.5 rounded font-bold">PROMO</span>}
61	            </div>
62	          </div>
63	
64	          {somenteVitrine ? null : !indisponivel ? (
65	            <div className="flex items-center gap-2 flex-shrink-0">
66	              {qtd === 0 ? (
67	                <motion.button whileTap={{ scale: 0.92 }} onClick={() => onAdicionar(produto, precoFinal)}
68	                  className="px-3.5 py-1.5 bg-[#FF441F] text-white text-xs font-bold rounded-xl hover:bg-[#E63A19] transition-colors">
69	                  Adicionar
70	                </motion.button>
71	              ) : (
72	                <div className="flex items-center gap-2">
73	                  <button onClick={() => onAdicionar(produto, precoFinal, -1)}
74	                    className="w-7 h-7 bg-[#F4F4F5] rounded-full font-bold text-[#27272A] flex items-center justify-center hover:bg-[#E4E4E7] text-base">−</button>
75	                  <span className="text-sm font-bold text-[#18181B] w-5 text-center">{qtd}</span>
76	                  <button onClick={() => onAdicionar(produto, precoFinal, +1)}
77	                    className="w-7 h-7 bg-[#FF441F] rounded-full font-bold text-white flex items-center justify-center hover:bg-[#E63A19] text-base">+</button>
78	                </div>
79	              )}
80	            </div>
81	          ) : (
82	            <span className="text-xs text-[#71717A] bg-[#F4F4F5] px-2 py-1 rounded-lg">Indisponível</span>
83	          )}
84	        </div>
85	      </div>
86	
87	      {produto.image_url && (
88	        <div className="relative flex-shrink-0 w-28 h-24">
89	          <img src={produto.image_url} alt={produto.name} className="w-full h-full object-cover rounded-xl" />
90	          {indisponivel && (
91	            <div className="absolute inset-0 bg-white/60 rounded-xl flex items-center justify-center">
92	              <span className="text-[10px] text-[#71717A] font-semibold">Indisponível</span>
93	            </div>
94	          )}
95	        </div>
96	      )}
97	    </motion.div>
98	  );
99	};
100	
101	/* ── Carrossel de combos ativos (topo da loja) ────────────────────── */
102	const ComboCarrosselCard = ({ combo, onAdicionar, restauranteFechado, somenteVitrine }) => {
103	  const temPromo = combo.preco_promo != null;
104	  const precoFinal = temPromo ? combo.preco_promo : combo.price;
105	
106	  return (
107	    <button
108	      onClick={() => !restauranteFechado && !somenteVitrine && onAdicionar(combo, precoFinal)}
109	      disabled={restauranteFechado || somenteVitrine}
110	      className={`flex-shrink-0 w-36 sm:w-40 bg-white rounded-2xl border overflow-hidden text-left relative ${
111	        restauranteFechado ? 'border-[#E4E4E7] opacity-60' : somenteVitrine ? 'border-[#E4E4E7] cursor-default' : 'border-[#E4E4E7] hover:shadow-md hover:border-[#FF441F]/30'
112	      }`}
113	    >
114	      <div className="relative h-28 bg-[#F4F4F5]">
115	        {combo.image_url
116	          ? <img src={combo.image_url} alt={combo.name} className="w-full h-full object-cover" />
117	          : <div className="w-full h-full flex items-center justify-center"><Icon name="Package" size={28} className="text-[#E4E4E7]" /></div>}
118	        <span className="absolute top-2 left-2 text-[9px] font-bold bg-[#FF441F] text-white px-1.5 py-0.5 rounded-full shadow">COMBO</span>
119	      </div>
120	      <div className="p-2.5">
121	        <p className="text-xs font-bold text-[#18181B] line-clamp-2 leading-tight">{combo.name}</p>
122	        <div className="mt-1.5">
123	          {temPromo && <p className="text-[9px] line-through text-[#71717A]">{fmt(combo.price)}</p>}
124	          <p className={`text-sm font-black ${temPromo ? 'text-green-600' : 'text-[#FF441F]'}`}>{fmt(precoFinal)}</p>
125	        </div>
126	      </div>
127	    </button>
128	  );
129	};
130	
131	const ComboCarrossel = ({ combos, onAdicionar, restauranteFechado, somenteVitrine }) => {
132	  const scrollRef = useRef(null);
133	  const scroll = (dir) => {
134	    if (scrollRef.current) scrollRef.current.scrollBy({ left: dir * 200, behavior: 'smooth' });
135	  };
136	
137	  return (
138	    <div className="relative">
139	      <button onClick={() => scroll(-1)}
140	        className="absolute left-0 top-1/2 -translate-y-1/2 z-10 w-8 h-8 bg-white border border-[#E4E4E7] rounded-full shadow flex items-center justify-center hover:bg-[#F4F4F5] -ml-4 hidden sm:flex">
141	        <Icon name="ChevronLeft" size={16} className="text-[#27272A]" />
142	      </button>
143	      <div ref={scrollRef} className="flex gap-3 overflow-x-auto pb-1" style={{ scrollbarWidth: 'none' }}>
144	        {combos.map((c) => (
145	          <ComboCarrosselCard key={c.id} combo={c} onAdicionar={onAdicionar} restauranteFechado={restauranteFechado} somenteVitrine={somenteVitrine} />
146	        ))}
147	      </div>
148	      <button onClick={() => scroll(1)}
149	        className="absolute right-0 top-1/2 -translate-y-1/2 z-10 w-8 h-8 bg-white border border-[#E4E4E7] rounded-full shadow flex items-center justify-center hover:bg-[#F4F4F5] -mr-4 hidden sm:flex">
150	        <Icon name="ChevronRight" size={16} className="text-[#27272A]" />
151	      </button>
152	    </div>
153	  );
154	};
155	
156	/* ── Conteúdo do carrinho (mobile + desktop) ─────────────────────── */
157	const CarrinhoConteudo = ({ carrinho, onAdicionar, onFechar, onCheckout }) => {
158	  const totalItens = carrinho.reduce((acc, i) => acc + i.qtd, 0);
159	  const totalValor = carrinho.reduce((acc, i) => acc + i.price * i.qtd, 0);
160	
161	  return (
162	    <>
163	      <div className="flex items-center justify-between px-5 pt-4 pb-3 border-b border-[#E4E4E7] flex-shrink-0">
164	        <h3 className="font-bold text-[#18181B] text-base">
165	          Carrinho <span className="text-[#FF441F]">({totalItens})</span>
166	        </h3>
167	        {onFechar && (
168	          <button onClick={onFechar} className="p-1.5 hover:bg-[#F4F4F5] rounded-lg">
169	            <Icon name="X" size={18} className="text-[#71717A]" />
170	          </button>
171	        )}
172	      </div>
173	
174	      <div className="flex-1 overflow-y-auto px-5 py-4 space-y-3">
175	        <AnimatePresence>
176	          {carrinho.map((item) => (
177	            <motion.div key={item.id} initial={{ opacity: 0, x: 16 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: 16 }}
178	              className="flex items-center gap-3">
179	              {item.image_url && (
180	                <img src={item.image_url} alt={item.name} className="w-12 h-12 rounded-xl object-cover flex-shrink-0" />
181	              )}
182	              <div className="flex-1 min-w-0">
183	                <p className="text-sm font-medium text-[#18181B] truncate">{item.name}</p>
184	                <p className="text-xs text-[#71717A]">{fmt(item.price)}</p>
185	              </div>
186	              <div className="flex items-center gap-1.5 flex-shrink-0">
187	                <button onClick={() => onAdicionar(item, item.price, -1)}
188	                  className="w-6 h-6 bg-[#F4F4F5] rounded-full text-sm font-bold text-[#27272A] flex items-center justify-center">−</button>
189	                <span className="text-sm font-bold text-[#18181B] w-4 text-center">{item.qtd}</span>
190	                <button onClick={() => onAdicionar(item, item.price, +1)}
191	                  className="w-6 h-6 bg-[#FF441F] rounded-full text-sm font-bold text-white flex items-center justify-center">+</button>
192	              </div>
193	            </motion.div>
194	          ))}
195	        </AnimatePresence>
196	      </div>
197	
198	      <div className="px-5 py-4 border-t border-[#E4E4E7] flex-shrink-0">
199	        <div className="flex justify-between text-sm mb-1">
200	          <span className="text-[#71717A]">Subtotal</span>
201	          <span className="font-medium text-[#27272A]">{fmt(totalValor)}</span>
202	        </div>
203	        <div className="flex justify-between text-base font-bold mb-4">
204	          <span className="text-[#18181B]">Total</span>
205	          <span className="text-[#FF441F]">{fmt(totalValor)}</span>
206	        </div>
207	        <motion.button whileTap={{ scale: 0.98 }} onClick={onCheckout}
208	          className="w-full py-3.5 bg-[#FF441F] text-white font-bold rounded-2xl hover:bg-[#E63A19] transition-colors text-sm shadow-lg shadow-[#FF441F]/20">
209	          Finalizar pedido →
210	        </motion.button>
211	      </div>
212	    </>
213	  );
214	};
215	
216	/* ── Drawer mobile (bottom sheet) ────────────────────────────────── */
217	const CarrinhoMobile = ({ carrinho, onAdicionar, onFechar, onCheckout }) => (
218	  <>
219	    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
220	      onClick={onFechar} className="fixed inset-0 bg-black/40 z-40 lg:hidden" />
221	    <motion.div
222	      initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }}
223	      transition={{ type: 'spring', damping: 28, stiffness: 300 }}
224	      className="fixed bottom-0 left-0 right-0 z-50 bg-white rounded-t-3xl shadow-2xl lg:hidden max-h-[82vh] flex flex-col"
225	    >
226	      <div className="w-10 h-1 bg-[#E4E4E7] rounded-full mx-auto mt-3 mb-1 flex-shrink-0" />
227	      <CarrinhoConteudo carrinho={carrinho} onAdicionar={onAdicionar} onFechar={onFechar} onCheckout={onCheckout} />
228	    </motion.div>
229	  </>
230	);
231	
232	/* ── Sidebar desktop ─────────────────────────────────────────────── */
233	const CarrinhoDesktop = ({ carrinho, onAdicionar, onCheckout }) => (
234	  <aside className="hidden lg:block w-80 xl:w-96 flex-shrink-0">
235	    <div className="sticky top-28 bg-white rounded-2xl border border-[#E4E4E7] shadow-sm overflow-hidden flex flex-col max-h-[calc(100vh-120px)]">
236	      {carrinho.length === 0 ? (
237	        <div className="flex flex-col items-center justify-center py-16 px-6 text-center">
238	          <Icon name="ShoppingCart" size={44} className="text-[#E4E4E7] mb-3" />
239	          <p className="text-sm font-semibold text-[#27272A]">Carrinho vazio</p>
240	          <p className="text-xs text-[#71717A] mt-1">Adicione itens do cardápio</p>
241	        </div>
242	      ) : (
243	        <CarrinhoConteudo carrinho={carrinho} onAdicionar={onAdicionar} onFechar={null} onCheckout={onCheckout} />
244	      )}
245	    </div>
246	  </aside>
247	);
248	
249	/* ── Componente principal ────────────────────────────────────────── */
250	const RestauranteCatalogo = ({ dadosPreCarregados } = {}) => {
251	  const { slug: slugParam } = useParams();
252	  const navigate = useNavigate();
253	  const { isAuthenticated, isRestaurantOwner, isAdmin } = useAuth();
254	  const [data, setData] = useState(dadosPreCarregados ?? null);
255	  const [loading, setLoading] = useState(!dadosPreCarregados);
256	  const [erro, setErro] = useState(null);
257	  const [carrinho, setCarrinho] = useState([]);
258	  const [catAtiva, setCatAtiva] = useState('todos');
259	  const [carrinhoAberto, setCarrinhoAberto] = useState(false);
260	
261	  // Quando aberto via domínio customizado (dadosPreCarregados vindo do HomeRouter),
262	  // não existe :slug na URL — o fetch abaixo é pulado, os dados já chegam prontos.
263	  useEffect(() => {
264	    if (dadosPreCarregados) return;
265	    setLoading(true);
266	    getCardapioPorSlug(slugParam)
267	      .then((d) => {
268	        setData(d);
269	        setCatAtiva('todos');
270	      })
271	      .catch((e) => setErro(e.message))
272	      .finally(() => setLoading(false));
273	  }, [slugParam, dadosPreCarregados]);
274	
275	  // Slug efetivo pro checkout: vem da URL em /r/:slug, ou do próprio payload
276	  // quando a loja foi aberta pelo domínio customizado (sem slug na URL).
277	  const slug = slugParam ?? data?.restaurante?.slug;
278	
279	  // Combo e produto têm sequências de id independentes — pode colidir (combo #5 e
280	  // produto #5), então a chave do carrinho precisa considerar o tipo junto do id.
281	  const chaveCarrinho = (item) => `${item.tipo === 'combo' ? 'combo' : 'produto'}-${item.id}`;
282	
283	  const altCarrinho = (produto, preco, delta = 1) => {
284	    setCarrinho((prev) => {
285	      const chave = chaveCarrinho(produto);
286	      const idx = prev.findIndex((i) => chaveCarrinho(i) === chave);
287	      if (idx >= 0) {
288	        const novo = [...prev];
289	        const novaQtd = novo[idx].qtd + delta;
290	        if (novaQtd <= 0) { novo.splice(idx, 1); return novo; }
291	        novo[idx] = { ...novo[idx], qtd: novaQtd };
292	        return novo;
293	      }
294	      if (delta < 0) return prev;
295	      return [...prev, { ...produto, price: preco, qtd: 1 }];
296	    });
297	  };
298	
299	  const qtdNoCarrinho = (produto) => carrinho.find((i) => chaveCarrinho(i) === chaveCarrinho(produto))?.qtd ?? 0;
300	  const totalItens = carrinho.reduce((acc, i) => acc + i.qtd, 0);
301	  const totalValor = carrinho.reduce((acc, i) => acc + i.price * i.qtd, 0);
302	
303	  const irParaCheckout = () => {
304	    const restauranteId = data?.restaurante?.id;
305	    const freteMotoboy = parseFloat(data?.restaurante?.frete_motoboy ?? 0);
306	    if (!isAuthenticated()) {
307	      sessionStorage.setItem('pending_cart', JSON.stringify({ carrinho, restauranteSlug: slug, restauranteId, freteMotoboy }));
308	      navigate('/customer-registration-login', { state: { from: '/shopping-cart-checkout' } });
309	      return;
310	    }
311	    navigate('/shopping-cart-checkout', { state: { carrinho, restauranteSlug: slug, restauranteId, freteMotoboy } });
312	  };
313	
314	  if (loading) return (
315	    <div className="min-h-screen bg-[#F4F4F5]">
316	      <div className="h-64 bg-gradient-to-br from-[#FF441F] to-[#FF7A00] animate-pulse" />
317	      <div className="max-w-screen-xl mx-auto px-4 py-6 grid grid-cols-1 xl:grid-cols-2 gap-3">
318	        {[...Array(6)].map((_, i) => <SkeletonProduto key={i} />)}
319	      </div>
320	    </div>
321	  );
322	
323	  if (erro) return (
324	    <div className="min-h-screen flex flex-col items-center justify-center bg-[#F4F4F5] p-6 text-center">
325	      <Icon name="Store" size={56} className="text-[#E4E4E7] mb-4" />
326	      <p className="text-lg font-semibold text-[#27272A]">Restaurante não encontrado</p>
327	      <p className="text-sm text-[#71717A] mt-1">{erro}</p>
328	      <button onClick={() => navigate(-1)} className="mt-6 px-4 py-2.5 bg-[#FF441F] text-white rounded-xl text-sm font-semibold">Voltar</button>
329	    </div>
330	  );
331	
332	  const { restaurante, cardapio, destaques, promos, combos } = data;
333	  const ap = restaurante.aparencia ?? {};
334	  // Sem plano delivery, a loja funciona só como vitrine — sem carrinho/checkout.
335	  const temDelivery = restaurante.modulo_delivery !== false;
336	
337	  const tabs = [
338	    { id: 'todos', label: 'Todos' },
339	    ...(destaques?.length ? [{ id: 'destaques', label: '⭐ Destaques' }] : []),
340	    ...(promos?.length ? [{ id: 'promos', label: '🔥 Promoções' }] : []),
341	    ...(combos?.length ? [{ id: 'combos', label: '🍱 Combos' }] : []),
342	    ...cardapio.map((c) => ({ id: c.id, label: c.name })),
343	  ];
344	
345	  const produtosDaTab = () => {
346	    if (catAtiva === 'todos') return cardapio.flatMap((c) => c.produtos ?? []);
347	    if (catAtiva === 'destaques') return destaques ?? [];
348	    if (catAtiva === 'promos') return promos ?? [];
349	    if (catAtiva === 'combos') return combos ?? [];
350	    return cardapio.find((c) => c.id === catAtiva)?.produtos ?? [];
351	  };
352	
353	  const bgStyle = ap.background_url
354	    ? { backgroundImage: `url(${ap.background_url})`, backgroundSize: 'cover', backgroundAttachment: 'fixed' }
355	    : ap.background_color
356	    ? { backgroundColor: ap.background_color }
357	    : {};
358	
359	  return (
360	    <div className="min-h-screen bg-[#F4F4F5]" style={bgStyle}>
361	
362	      {/* ── Header global ──────────────────────────────────────────── */}
363	      <header className="sticky top-0 z-30 bg-white/95 backdrop-blur-md border-b border-[#E4E4E7]">
364	        <div className="max-w-screen-xl mx-auto px-4 h-14 flex items-center gap-3">
365	          <button
366	            onClick={() => { if (window.history.length > 1) navigate(-1); else navigate('/'); }}
367	            className="p-2 hover:bg-[#F4F4F5] rounded-lg text-[#71717A] hover:text-[#27272A] transition-colors"
368	          >
369	            <Icon name="ArrowLeft" size={18} />
370	          </button>
371	          <div className="flex items-center gap-2">
372	            <div className="w-7 h-7 bg-[#FF441F] rounded-lg flex items-center justify-center shadow-sm shadow-[#FF441F]/30">
373	              <Icon name="Utensils" size={14} className="text-white" />
374	            </div>
375	            <span className="font-black text-[#18181B] text-sm hidden sm:block">DeliveryHub</span>
376	          </div>
377	          <div className="flex-1 min-w-0">
378	            <p className="font-semibold text-[#18181B] text-sm truncate">{restaurante.name}</p>
379	          </div>
380	          {/* Botão painel restaurante — visível para dono */}
381	          {isRestaurantOwner() && (
382	            <button onClick={() => navigate('/restaurante')}
383	              className="p-2 text-[#FF441F] hover:bg-[#FF441F]/5 rounded-lg flex-shrink-0" title="Meu Painel">
384	              <Icon name="Store" size={18} />
385	            </button>
386	          )}
387	          {/* Botões cliente — pedidos e perfil */}
388	          {isAuthenticated() && !isRestaurantOwner() && !isAdmin() && (
389	            <button onClick={() => navigate('/customer-account-order-history')}
390	              className="p-2 text-[#71717A] hover:text-[#FF441F] hover:bg-[#FF441F]/5 rounded-lg flex-shrink-0 transition-colors"
391	              title="Meus Pedidos">
392	              <Icon name="ClipboardList" size={18} />
393	            </button>
394	          )}
395	          {!isAuthenticated() && (
396	            <button onClick={() => navigate('/customer-registration-login')}
397	              className="flex items-center gap-1.5 px-2.5 sm:px-3 py-1.5 text-sm font-semibold text-[#FF441F] border border-[#FF441F]/30 hover:bg-[#FF441F]/5 rounded-lg flex-shrink-0 transition-colors"
398	              title="Entrar">
399	              <Icon name="LogIn" size={16} />
