  className={`flex gap-4 p-4 bg-white rounded-2xl border transition-all h-full ${
    indisponivel ? 'border-[#E4E4E7] opacity-60' : 'border-[#E4E4E7] hover:shadow-md hover:border-[#FF441F]/20'
  }`}
>
