const fs = require('fs');
const content = fs.readFileSync('src/pages/restaurante-catalogo/index.jsx', 'utf8');
const patterns = [
  /bg-white(?!\/)/g, /text-\[#18181B\]/g, /text-\[#71717A\]/g, /border-\[#E4E4E7\]/g,
  /bg-\[#F4F4F5\]/g, /bg-\[#FAFAFA\]/g, /bg-\[#E4E4E7\]/g, /text-\[#E4E4E7\]/g
];
const lines = content.split('\n');
lines.forEach((line, i) => {
  patterns.forEach(p => {
    p.lastIndex = 0;
    let m;
    while ((m = p.exec(line))) {
      // check if dark: appears nearby after this match within next 60 chars
      const after = line.slice(m.index, m.index+80);
      if (!after.includes('dark:')) {
        console.log((i+1)+': '+line.trim());
      }
    }
  });
});
"

