const fs = require('fs');
const content = fs.readFileSync('src/pages/shopping-cart-checkout/index.jsx', 'utf8');
const patterns = [
  /bg-white(?!\/)/g, /text-\[#18181B\]/g, /text-\[#71717A\]/g, /border-\[#E4E4E7\]/g,
  /bg-\[#F4F4F5\]/g, /bg-\[#FAFAFA\]/g, /bg-\[#E4E4E7\]/g, /text-\[#E4E4E7\]/g,
  /bg-green-100/g,/text-green-600/g,/bg-blue-50/g,/text-blue-700/g,/border-blue-100/g,
  /bg-red-50/g,/text-red-600/g,/border-red-200/g
];
const lines = content.split('\n');
lines.forEach((line, i) => {
  patterns.forEach(p => {
    p.lastIndex = 0;
    let m;
    while ((m = p.exec(line))) {
      const after = line.slice(m.index, m.index+80);
      if (!after.includes('dark:')) {
        console.log((i+1)+': '+line.trim());
      }
    }
  });
});
