6	
7	const formatCEP = (v) => {
8	  const n = (v ?? '').replace(/\D/g, '');
9	  return n.length <= 8 ? n.replace(/(\d{5})(\d{0,3})/, (_, a, b) => (b ? `${a}-${b}` : a)) : v;
10	};
11	
12	const Campo = ({ label, value, onChange, placeholder, required, half }) => (
13	  <div className={half ? 'w-1/2' : 'w-full'}>
14	    <label className="block text-xs font-medium text-[#71717A] mb-1">{label}{required && <span className="text-red-500 ml-0.5">*</span>}</label>
15	    <input
16	      value={value}
17	      onChange={(e) => onChange(e.target.value)}
18	      placeholder={placeholder}
19	      className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:border-[#FF441F]"
20	    />
21	  </div>
22	);
23	
24	const StepEndereco = ({ perfil, onNext, onBack }) => {
25	  const [form, setForm] = useState({
26	    name: '', phone_e164: '',
27	    logradouro: '', numero: '', complemento: '',
28	    bairro: '', cidade: '', estado: '', cep: '', referencia: '',
29	  });
30	  const [salvando, setSalvando] = useState(false);
31	  const [erro, setErro] = useState(null);
32	  const [buscandoCep, setBuscandoCep] = useState(false);
33	
34	  useEffect(() => {
35	    if (!perfil) return;
36	    const a = perfil.address_json ?? {};
37	    setForm({
38	      name: perfil.name ?? '',
39	      phone_e164: perfil.phone_e164 ?? '',
40	      logradouro: a.logradouro ?? '',
41	      numero: a.numero ?? '',
42	      complemento: a.complemento ?? '',
43	      bairro: a.bairro ?? '',
44	      cidade: a.cidade ?? '',
45	      estado: a.estado ?? '',
46	      cep: a.cep ?? '',
47	      referencia: a.referencia ?? '',
48	    });
49	  }, [perfil]);
50	
51	  const set = (k) => (v) => setForm((f) => ({ ...f, [k]: v }));
52	
53	  const handleCepChange = async (v) => {
54	    const formatted = formatCEP(v);
55	    setForm((f) => ({ ...f, cep: formatted }));
56	
57	    const digitos = formatted.replace(/\D/g, '');
58	    if (digitos.length !== 8) return;
59	    setBuscandoCep(true);
60	    const endereco = await buscarCep(digitos);
61	    setBuscandoCep(false);
62	    if (!endereco) return;
63	    setForm((f) => ({
64	      ...f,
65	      logradouro: endereco.logradouro || f.logradouro,
66	      bairro: endereco.bairro || f.bairro,
67	      cidade: endereco.cidade || f.cidade,
68	      estado: endereco.estado || f.estado,
69	    }));
70	  };
71	
72	  const handleNext = async () => {
73	    if (!form.name.trim() || !form.phone_e164.trim() || !form.logradouro.trim() || !form.numero.trim()) {
74	      setErro('Preencha nome, telefone, endereço e número.');
75	      return;
76	    }
77	    setSalvando(true);
78	    setErro(null);
79	    try {
80	      const updated = await updatePerfil({
81	        name: form.name.trim(),
82	        phone_e164: form.phone_e164.trim(),
83	        address_json: {
84	          logradouro: form.logradouro.trim(),
85	          numero: form.numero.trim(),
86	          complemento: form.complemento.trim(),
87	          bairro: form.bairro.trim(),
88	          cidade: form.cidade.trim(),
89	          estado: form.estado.trim(),
90	          cep: form.cep.trim(),
91	          referencia: form.referencia.trim(),
92	        },
93	      });
94	      onNext(updated);
95	    } catch (e) {
96	      setErro(e.message);
97	    } finally {
