const fs = require('fs');
const content = fs.readFileSync('$f', 'utf8');
const patterns = [
  /bg-white(?!\/)/g, /text-\[#18181B\]/g, /text-\[#71717A\]/g, /border-\[#E4E4E7\]/g,
  /bg-\[#F4F4F5\]/g, /bg-\[#FAFAFA\]/g, /bg-\[#E4E4E7\]/g, /text-\[#E4E4E7\]/g, /border-\[#F4F4F5\]/g,
