input.command:
cd "C:\Users\jotac\OneDrive\Documents\DEV\deliveryhub_white_label" && for f in \
  "src/pages/restaurante-catalogo/index.jsx" \
  "src/pages/shopping-cart-checkout/index.jsx" \
  "src/pages/shopping-cart-checkout/StepEndereco.jsx" \
  "src/pages/shopping-cart-checkout/MultiCartCheckout.jsx" \
  "src/pages/cardapio-digital/index.jsx" \
  "src/pages/mesa-acompanhar/index.jsx" \
  "src/pages/auto-atendimento/index.jsx"; do
echo "=== $f ==="
node -e "
const fs = require('fs');
const content = fs.readFileSync('$f', 'utf8');
const patterns = [
  /bg-white(?!\/)/g, /text-\[#18181B\]/g, /text-\[#71717A\]/g, /border-\[#E4E4E7\]/g,
  /bg-\[#F4F4F5\]/g, /bg-\[#FAFAFA\]/g, /bg-\[#E4E4E7\]/g, /text-\[#E4E4E7\]/g, /border-\[#F4F4F5\]/g,
  /bg-blue-50/g,/text-blue-700/g,/text-blue-600/g,/border-blue-200/g,
  /bg-red-50/g,/text-red-600/g,/border-red-200/g,/bg-red-100/g,/text-red-700/g,
  /bg-green-100/g,/text-green-600/g,/bg-green-700/g,
  /bg-emerald-100/g,/text-emerald-700/g,/text-emerald-600/g,
  /bg-orange-100/g,/text-orange-700/g,
  /bg-zinc-100/g,/text-zinc-600/g,
  /bg-yellow-400\/20/g,/text-yellow-700/g,
  /bg-amber-100/g,/text-amber-700/g
];
const lines = content.split('\n');
lines.forEach((line, i) => {
  patterns.forEach(p => {
    p.lastIndex = 0;
    let m;
    while ((m = p.exec(line))) {
      const after = line.slice(m.index, m.index+90);
      if (!after.includes('dark:')) console.log((i+1)+': '+line.trim());
    }
  });
});
"
done

